CREATE OR REPLACE FUNCTION public.ph2_channel_allowed(_channel text,_product_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(value @> '{"enabled":true,"backup_verified":true,"restore_verified":true,"communication_verified":true}'::jsonb AND coalesce((value->>'emergency_stopped')::boolean,true)=false AND length(coalesce(value->>'approved_by',''))>0 AND _channel IN ('de','com') AND (value->'channels'->_channel->>'mode'='full' OR (value->'channels'->_channel->>'mode'='pilot' AND value->'channels'->_channel->>'pilot_product_id'=_product_id::text)),false) FROM public.ph_settings WHERE key='ph2_activation'; $$;
REVOKE ALL ON FUNCTION public.ph2_channel_allowed(text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ph2_channel_allowed(text,uuid) TO service_role;
UPDATE public.ph_settings SET value=value||jsonb_build_object('controlled_modes',true,'emergency_stopped',true,'revision',0,'channels',jsonb_build_object('de',jsonb_build_object('mode','blocked','pilot_product_id',null),'com',jsonb_build_object('mode','blocked','pilot_product_id',null))) WHERE key='ph2_activation' AND NOT value ? 'controlled_modes';
CREATE OR REPLACE FUNCTION public.ph2_guard_reserved() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE reserved boolean; BEGIN IF TG_TABLE_NAME='ph_settings' THEN reserved:=(TG_OP<>'INSERT' AND OLD.key LIKE 'ph2_%') OR (TG_OP<>'DELETE' AND NEW.key LIKE 'ph2_%'); ELSE reserved:=(TG_OP<>'INSERT' AND OLD.operation LIKE 'ph2_%') OR (TG_OP<>'DELETE' AND NEW.operation LIKE 'ph2_%'); END IF; IF reserved AND current_user NOT IN ('postgres','supabase_admin','service_role') AND coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Geschützter PRODUCT-HUB-Nachweis oder Betriebsmodus'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;
CREATE OR REPLACE FUNCTION ph_signal_private.ph2_require_super_admin() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_profiles p JOIN public.user_roles ur ON ur.user_id=p.id JOIN public.roles r ON r.id=ur.role_id WHERE p.id=auth.uid() AND p.account_status='active' AND p.invitation_status='accepted' AND p.password_reset_required=false AND r.name='Super Admin') THEN RAISE EXCEPTION 'Nur ein aktiver Super Admin darf den Betriebsmodus ändern oder Prüfnachweise erfassen'; END IF; END $$;
REVOKE ALL ON FUNCTION ph_signal_private.ph2_require_super_admin() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION ph_signal_private.ph2_set_operating_mode(_channel text,_mode text,_pilot uuid,_confirmation text,_revision integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g public.ph_settings; next_value jsonb; latest jsonb; selected uuid; checks integer; BEGIN PERFORM ph_signal_private.ph2_require_super_admin(); IF _channel NOT IN ('de','com') OR _mode NOT IN ('blocked','pilot','full') OR _channel IS NULL OR _mode IS NULL THEN RAISE EXCEPTION 'Ungültige Webseite oder Betriebsmodus'; END IF; IF _confirmation IS DISTINCT FROM ('FREIGABE '||upper(_channel)||' '||upper(_mode)) THEN RAISE EXCEPTION 'Ausdrückliche Sicherheitsbestätigung fehlt'; END IF; SELECT * INTO g FROM public.ph_settings WHERE key='ph2_activation' FOR UPDATE; IF _revision IS DISTINCT FROM coalesce((g.value->>'revision')::integer,0) THEN RAISE EXCEPTION 'Betriebsmodus wurde inzwischen geändert; bitte neu laden'; END IF; selected:=CASE WHEN _mode='pilot' THEN _pilot ELSE nullif(g.value->'channels'->_channel->>'pilot_product_id','')::uuid END; IF _mode<>'blocked' THEN IF NOT g.value @> '{"backup_verified":true,"restore_verified":true,"communication_verified":true}'::jsonb THEN RAISE EXCEPTION 'Freigabe gesperrt: Nachweis für Vollsicherung, Wiederherstellung oder Kommunikation fehlt'; END IF; SELECT payload INTO latest FROM public.ph_sync_log WHERE operation='ph2_connection_test' AND channel_code=_channel ORDER BY created_at DESC LIMIT 1; IF latest->>'result' IS DISTINCT FROM 'accepted' OR latest->>'signature' IS DISTINCT FROM 'verified' OR latest->>'receipt' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Freigabe gesperrt: aktuelle technische Abnahme fehlt'; END IF; IF selected IS NULL OR NOT EXISTS(SELECT 1 FROM public.ph_products WHERE id=selected) THEN RAISE EXCEPTION 'Genau ein vorhandenes Pilotgerät auswählen'; END IF; SELECT payload INTO latest FROM public.ph_sync_log WHERE operation='ph2_pilot_check' AND channel_code=_channel AND product_id=selected AND payload->>'check'='receiver_readiness' ORDER BY created_at DESC LIMIT 1; IF latest->>'passed' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Freigabe gesperrt: Pilotgeräte-Sperre des Empfängers ist noch nicht nachgewiesen'; END IF; IF _mode='full' THEN SELECT count(*) INTO checks FROM (SELECT DISTINCT ON(payload->>'check') payload FROM public.ph_sync_log WHERE operation='ph2_pilot_check' AND channel_code=_channel AND product_id=selected ORDER BY payload->>'check',created_at DESC) c WHERE c.payload->>'passed'='true' AND c.payload->>'check' IN ('data','images','technical','offline','online','cache','display'); IF checks<>7 THEN RAISE EXCEPTION 'Vollbetrieb gesperrt: vollständige Pilot-Synchronisationsprüfung fehlt'; END IF; END IF; END IF; next_value:=jsonb_set(g.value,ARRAY['channels',_channel],jsonb_build_object('mode',_mode,'pilot_product_id',CASE WHEN _mode='blocked' THEN NULL ELSE selected END,'approved_by',auth.uid(),'approved_at',clock_timestamp())); next_value:=next_value||jsonb_build_object('revision',_revision+1,'approved_by',auth.uid(),'emergency_stopped',CASE WHEN _mode='blocked' THEN coalesce((g.value->>'emergency_stopped')::boolean,true) ELSE false END); next_value:=next_value||jsonb_build_object('enabled',coalesce(next_value->'channels'->'de'->>'mode'<>'blocked',false) OR coalesce(next_value->'channels'->'com'->>'mode'<>'blocked',false)); UPDATE public.ph_settings SET value=next_value,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=g.id; UPDATE public.ph_sync_log SET status='superseded',message='Betriebsmodus geändert; keine automatische Wiederholung' WHERE operation='ph2_signal' AND channel_code=_channel AND status NOT IN ('website_confirmed','superseded'); INSERT INTO public.ph_sync_log(channel_code,direction,operation,status,message,payload) VALUES(_channel,'internal','ph2_mode_change','ok','Betriebsmodus ausdrücklich bestätigt',jsonb_build_object('before',g.value->'channels'->_channel,'after',next_value->'channels'->_channel,'requested_by',auth.uid(),'revision',_revision+1)); RETURN next_value; END $$;
REVOKE ALL ON FUNCTION ph_signal_private.ph2_set_operating_mode(text,text,uuid,text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION ph_signal_private.ph2_set_operating_mode(text,text,uuid,text,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.ph2_set_operating_mode(_channel text,_mode text,_pilot uuid,_confirmation text,_revision integer) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT ph_signal_private.ph2_set_operating_mode(_channel,_mode,_pilot,_confirmation,_revision) $$;
REVOKE ALL ON FUNCTION public.ph2_set_operating_mode(text,text,uuid,text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.ph2_set_operating_mode(text,text,uuid,text,integer) TO authenticated;
CREATE OR REPLACE FUNCTION ph_signal_private.ph2_stop_production() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g public.ph_settings; v jsonb; BEGIN PERFORM ph_signal_private.ph2_require_super_admin(); SELECT * INTO g FROM public.ph_settings WHERE key='ph2_activation' FOR UPDATE; v:=g.value||jsonb_build_object('enabled',false,'emergency_stopped',true,'revision',coalesce((g.value->>'revision')::integer,0)+1,'channels',jsonb_build_object('de',jsonb_build_object('mode','blocked','pilot_product_id',null),'com',jsonb_build_object('mode','blocked','pilot_product_id',null))); UPDATE public.ph_settings SET value=v,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=g.id; UPDATE public.ph_sync_log SET status='superseded',message='Notabschaltung: weitere Übertragungen gesperrt' WHERE operation='ph2_signal' AND channel_code IN ('de','com') AND direction='outbound' AND status NOT IN ('website_confirmed','superseded'); INSERT INTO public.ph_sync_log(direction,operation,status,message,payload) VALUES('internal','ph2_emergency_stop','ok','Produktivbetrieb DE und COM sofort gesperrt',jsonb_build_object('requested_by',auth.uid(),'before',g.value->'channels','revision',v->'revision')); RETURN v; END $$;
REVOKE ALL ON FUNCTION ph_signal_private.ph2_stop_production() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION ph_signal_private.ph2_stop_production() TO authenticated;
CREATE OR REPLACE FUNCTION public.ph2_stop_production() RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT ph_signal_private.ph2_stop_production() $$;
REVOKE ALL ON FUNCTION public.ph2_stop_production() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.ph2_stop_production() TO authenticated;
CREATE OR REPLACE FUNCTION ph_signal_private.ph2_record_pilot_check(_channel text,_product uuid,_check text,_passed boolean,_evidence text,_event uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.ph_sync_log; BEGIN PERFORM ph_signal_private.ph2_require_super_admin(); IF _channel IS NULL OR _channel NOT IN ('de','com') OR _check IS NULL OR _check NOT IN ('receiver_readiness','data','images','technical','offline','online','cache','display') OR _passed IS NULL OR length(trim(coalesce(_evidence,'')))<10 OR length(_evidence)>2000 THEN RAISE EXCEPTION 'Prüfung und konkreten Nachweis (10–2000 Zeichen) angeben'; END IF; IF NOT EXISTS(SELECT 1 FROM public.ph_products WHERE id=_product) THEN RAISE EXCEPTION 'Gerät nicht vorhanden'; END IF; IF _check<>'receiver_readiness' AND _passed THEN SELECT * INTO q FROM public.ph_sync_log WHERE id=_event AND operation='ph2_signal' AND channel_code=_channel AND product_id=_product; IF NOT FOUND OR q.status<>'website_confirmed' OR q.direction<>'outbound' OR q.payload->'receipt'->>'version' IS DISTINCT FROM q.payload->'signal'->>'version' THEN RAISE EXCEPTION 'Erfolgreicher Prüfnachweis erfordert eine passende signierte produktive Empfangsbestätigung'; END IF; IF _check='offline' AND q.payload->'receipt'->>'state'<>'OFFLINE' OR _check='online' AND q.payload->'receipt'->>'state'<>'ONLINE' THEN RAISE EXCEPTION 'Empfangsbestätigung passt nicht zum geprüften Zustand'; END IF; END IF; INSERT INTO public.ph_sync_log(channel_code,product_id,direction,operation,status,message,payload) VALUES(_channel,_product,'internal','ph2_pilot_check',CASE WHEN _passed THEN 'ok' ELSE 'error' END,_evidence,jsonb_build_object('check',_check,'passed',_passed,'evidence',_evidence,'event_id',_event,'requested_by',auth.uid(),'verification','manual_evidence','signed_receipt',q.payload->'receipt')); END $$;
REVOKE ALL ON FUNCTION ph_signal_private.ph2_record_pilot_check(text,uuid,text,boolean,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION ph_signal_private.ph2_record_pilot_check(text,uuid,text,boolean,text,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.ph2_record_pilot_check(_channel text,_product uuid,_check text,_passed boolean,_evidence text,_event uuid DEFAULT NULL) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT ph_signal_private.ph2_record_pilot_check(_channel,_product,_check,_passed,_evidence,_event) $$;
REVOKE ALL ON FUNCTION public.ph2_record_pilot_check(text,uuid,text,boolean,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.ph2_record_pilot_check(text,uuid,text,boolean,text,uuid) TO authenticated;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.ph2_capture(uuid,text)'::regprocedure) INTO def; def:=replace(def,' SELECT coalesce((value->>''enabled'')::boolean,false) INTO active FROM public.ph_settings WHERE key=''ph2_activation'';',''); def:=replace(def,' FOREACH ch IN ARRAY ARRAY[''de'',''com'',''dubai''] LOOP',' FOREACH ch IN ARRAY ARRAY[''de'',''com'',''dubai''] LOOP'||chr(10)||'  active:=public.ph2_channel_allowed(ch,p.id);'); def:=replace(def,'''source'',_source)', '''source'',_source,''changed_sources'',coalesce(prev.payload->''changed_sources'',''[]''::jsonb)||to_jsonb(_source))'); def:=replace(def,'''source'',_source,''attempts''','''source'',_source,''changed_sources'',jsonb_build_array(_source),''attempts'''); IF position('active:=public.ph2_channel_allowed(ch,p.id)' in def)=0 THEN RAISE EXCEPTION 'Capture patch missing'; END IF; EXECUTE def; SELECT pg_get_functiondef('public.ph2_claim(boolean,integer)'::regprocedure) INTO def; def:=replace(def,'AND coalesce((payload->>''next_attempt_at'')','AND (NOT _live OR public.ph2_channel_allowed(channel_code,product_id)) AND coalesce((payload->>''next_attempt_at'')'); IF position('public.ph2_channel_allowed(channel_code,product_id)' in def)=0 THEN RAISE EXCEPTION 'Claim patch missing'; END IF; EXECUTE def; SELECT pg_get_functiondef('public.ph2_prepare(uuid,uuid,jsonb,jsonb)'::regprocedure) INTO def; def:=replace(def,' UPDATE public.ph_sync_log SET payload=payload', ' IF q.direction=''outbound'' AND NOT public.ph2_channel_allowed(q.channel_code,q.product_id) THEN RETURN false; END IF;'||chr(10)||' UPDATE public.ph_sync_log SET payload=payload'); IF position('NOT public.ph2_channel_allowed(q.channel_code,q.product_id)' in def)=0 THEN RAISE EXCEPTION 'Prepare patch missing'; END IF; EXECUTE def; END $$;